def get_equipment_quantities(options):
    """Generate only the factions/paliers allowed by this world's YAML."""
    from .EquipmentPool import equipment_quantities
    quantities = equipment_quantities(EQUIPMENT_ITEMS, options)
    if bool(getattr(getattr(options, "group_armor_sets", None), "value", False)):
        from .ArmorSets import SETS
        for spec in SETS:
            values = [quantities.pop(name) for name in spec["members"]]
            if len(set(values)) != 1:
                raise ValueError(f"Armor set members have incompatible limits: {spec['name']}")
            quantities[spec["name"]] = values[0]
    return quantities
